/* @component: .mod-popup */
document.addEventListener('click', function(e) {
  // 1. Open Button Click
  const btn = e.target.closest('.btn-open');
  if (btn) {
    let modal = null;
    const targetId = btn.getAttribute('data-target');
    if (targetId) {
      modal = document.getElementById(targetId);
    } 

    // Ищем модалку рядом по DOM
    if (!modal) {
      let sibling = btn.nextElementSibling;
      while(sibling) {
        if (sibling.classList.contains('mod-popup')) {
          modal = sibling;
          break;
        }
        sibling = sibling.nextElementSibling;
      }
    }

    // Глобальный Fallback
    if (!modal) {
      modal = document.querySelector('.mod-popup');
    }

    if (modal) {
      const isOpening = !modal.classList.contains('_open');

      // ЗАКРЫВАЕМ ВСЕ ОСТАЛЬНЫЕ МОДАЛКИ
      document.querySelectorAll('.mod-popup._open').forEach(m => {
        if (m !== modal) {
          m.classList.remove('_open');
        }
      });

      if (isOpening) {
        modal.classList.add('_open');
        document.body.style.maxHeight = '100vh';
        document.body.style.overflow = 'hidden';
      } else {
        modal.classList.remove('_open');
        document.body.style.maxHeight = 'none';
        document.body.style.overflow = 'auto';
      }
    }
    return;
  }

  // 2. Клик по крестику
  const closeBtn = e.target.closest('.mod__close');
  if (closeBtn) {
    const modal = closeBtn.closest('.mod-popup');
    if (modal) {
      modal.classList.remove('_open');
      document.body.style.maxHeight = 'none';
      document.body.style.overflow = 'auto';
    }
    return;
  }

  // 3. Клик по оверлею (но НЕ внутри .mod__inner)
  const popup = e.target.closest('.mod-popup');
  if (popup) {
    const inner = e.target.closest('.mod__inner');
    if (!inner) {
      popup.classList.remove('_open');
      document.body.style.maxHeight = 'none';
      document.body.style.overflow = 'auto';
    }
  }
});
